SELECT ticket_trade.validar_integridad();
CREATE FUNCTION pg_temp.debe_rechazar(nombre text, sentencia text, codigo text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE recibido text;
BEGIN
 BEGIN
  SET CONSTRAINTS ALL DEFERRED;
  EXECUTE sentencia;
  SET CONSTRAINTS ALL IMMEDIATE;
  PERFORM ticket_trade.validar_integridad();
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS recibido=RETURNED_SQLSTATE;
  IF recibido<>codigo THEN RAISE EXCEPTION 'Prueba %: se esperaba %, se recibió % (%)',nombre,codigo,recibido,SQLERRM; END IF;
  RAISE NOTICE 'OK: %',nombre;
  RETURN;
 END;
 RAISE EXCEPTION 'Prueba %: se aceptó una operación inválida',nombre;
END $$;
