DO $$ BEGIN
 IF (SELECT count(*) FROM ticket_trade.v_pase_actividades WHERE id_boleto_evento=1001)<>2 THEN RAISE EXCEPTION 'El pase no conserva sus dos actividades'; END IF;
 IF (SELECT count(DISTINCT codigo_qr) FROM ticket_trade.v_pase_actividades WHERE id_boleto_evento=1001)<>1 THEN RAISE EXCEPTION 'QR distinto por actividad'; END IF;
 IF (SELECT count(*) FROM ticket_trade.v_asistentes_csv WHERE id_evento=1001)<>2 THEN RAISE EXCEPTION 'Filas CSV incorrectas'; END IF;
 IF (SELECT count(*) FROM ticket_trade.v_entradas_csv WHERE id_evento=1001)<>2 THEN RAISE EXCEPTION 'Entradas CSV incorrectas'; END IF;
 IF (SELECT estado_boleto FROM ticket_trade.v_pase_actividades WHERE id_reservacion=1001)<>'utilizado' OR (SELECT estado_boleto FROM ticket_trade.v_pase_actividades WHERE id_reservacion=1002)<>'valido' THEN RAISE EXCEPTION 'La entrada de una actividad consumió la otra'; END IF;
 IF ticket_trade.limite_revision('2026-11-06 10:00:00-06')<>'2026-11-11 00:00:00-06'::timestamptz THEN RAISE EXCEPTION 'No se omitió el fin de semana'; END IF;
 INSERT INTO ticket_trade."DiaInhabil" VALUES ('2026-11-09','Solo para probar omisión de inhábiles');
 IF ticket_trade.limite_revision('2026-11-06 10:00:00-06')<>'2026-11-12 00:00:00-06'::timestamptz THEN RAISE EXCEPTION 'No se omitió el día inhábil'; END IF;
 DELETE FROM ticket_trade."DiaInhabil" WHERE fecha='2026-11-09';
 END $$;
SAVEPOINT cancelacion_parcial;
SET CONSTRAINTS ALL DEFERRED;
UPDATE ticket_trade."Reservacion" SET id_estado_reservacion=2,cancelada_en=CURRENT_TIMESTAMP,id_causa_cancelacion_reservacion=1 WHERE id_reservacion=1002;
UPDATE ticket_trade."CompromisoCupo" SET id_estado_compromiso_cupo=2 WHERE id_compromiso_cupo=1002;
SELECT ticket_trade.validar_integridad();
DO $$ BEGIN
 IF (SELECT estado_boleto FROM ticket_trade.v_pase_actividades WHERE id_reservacion=1002)<>'cancelado' OR (SELECT estado_boleto FROM ticket_trade.v_pase_actividades WHERE id_reservacion=1001)<>'utilizado' OR (SELECT codigo_qr FROM ticket_trade."BoletoEvento" WHERE id_boleto_evento=1001)<>'TT-00000000000000000000000000000001' THEN RAISE EXCEPTION 'Cancelación parcial cambió el QR u otra actividad'; END IF;
END $$;
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK TO SAVEPOINT cancelacion_parcial;
SAVEPOINT conversion_apartado;
SET CONSTRAINTS ALL DEFERRED;
UPDATE ticket_trade."Apartado" SET id_estado_apartado=2 WHERE id_compromiso_cupo=1004;
INSERT INTO ticket_trade."Reservacion" (id_boleto_evento,id_compromiso_cupo,confirmada_en,id_estado_reservacion) VALUES(1001,1004,CURRENT_TIMESTAMP,1);
SELECT ticket_trade.validar_integridad();
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK TO SAVEPOINT conversion_apartado;

SAVEPOINT formatos_validos;
UPDATE ticket_trade."Estudiante" SET boleta='0000000001' WHERE id_cuenta=1004;
DO $$ BEGIN
 IF (SELECT boleta FROM ticket_trade."Estudiante" WHERE id_cuenta=1004)<>'0000000001' THEN RAISE EXCEPTION 'Se perdieron los ceros iniciales'; END IF;
END $$;
UPDATE ticket_trade."Estudiante" SET boleta='PE00123456' WHERE id_cuenta=1004;
UPDATE ticket_trade."Estudiante" SET boleta='PP00123456' WHERE id_cuenta=1004;
UPDATE ticket_trade."Archivo" SET tamano_bytes=5242880 WHERE id_archivo=1002;
SELECT ticket_trade.validar_integridad();
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK TO SAVEPOINT formatos_validos;
SET CONSTRAINTS ALL IMMEDIATE;
ROLLBACK;
SELECT 'Pruebas aprobadas; los datos ficticios se revirtieron' AS resultado;
